export const BILL_LOOKUP_LIMIT = 1000;

/**
 * Adds the condition of query.billFilter (merchantTransId of the original order) to `filter`. The orders are resolved on the first chunk
 * only: query.resolvedBillIds is reused by every other chunk of the job. No serviceCode on the orders: the orders of Rada have none.
 */
export const applyBillFilter = async (query: GetAllPartnerCollectionTransExportQuery, filter: any, Bill: any, logger?: any): Promise<void> => {
    const merchantTransId = query.billFilter?.merchantTransId?.trim();
    if (!merchantTransId) {
        return;
    }
    if (!query.resolvedBillIds) {
        const bills = await Bill.find({ merchantTransId: { $regex: _.escapeRegExp(merchantTransId), $options: "i" } })
            .select({ _id: 1 })
            .limit(BILL_LOOKUP_LIMIT)
            .lean()
            .exec();
        if ((bills || []).length >= BILL_LOOKUP_LIMIT) {
            logger?.warn(
                `[PartnerCollectionTransExport] merchantTransId "${merchantTransId}" matches at least ` +
                `${BILL_LOOKUP_LIMIT} orders: only the first ${BILL_LOOKUP_LIMIT} are exported`
            );
        }
        query.resolvedBillIds = (bills || []).flatMap((b: any) => billIdVariants(b._id));
    }
    // No order matched: an empty $in matches nothing, so the result is empty instead of dropping the condition
    filter.$and = [...(filter.$and || []), { "info.billId": { $in: query.resolvedBillIds } }];
};

